// MultiRegistryTagsMetaMsg carries last-updated times for tags from one registry (background enrichment).
type MultiRegistryTagsMetaMsg struct {
	EntryKey    string
	RegistryURL string
	Repo        string
	Meta        map[string]time.Time
	Err         error
}

// RegistryPullCompleteMsg signals the result of a docker pull initiated from the browser.
type RegistryPullCompleteMsg struct {
	ImageName string
	Err       error

	// The fields below belong to an update (G, §3.88) and are zero for a plain
	// pull. Replaces is the image the pull replaces; InUse the containers that
	// kept it from starting; Unchanged a pull that brought the same image;
	// RemoveErr why the replaced image could not be removed.
	Replaces  string
	InUse     []string
	Unchanged bool
	RemoveErr error
}

// RegistryPullRequestedMsg asks the parent model to launch a pull as a job.
// The browser emits this instead of calling docker.PullImage itself, so the
// pull is admitted through jobs.Start like the direct scan already is.
type RegistryPullRequestedMsg struct{ ImageName string }

// RegistryPullStartingMsg signals that a pull has been admitted and is running.
type RegistryPullStartingMsg struct {
	ImageName string

	// Cancel stops the pull, and is what makes `K` on this row mean anything
	// (D7) — cutting one leaves nothing behind, Docker resuming a pull by
	// layer. It rides on the starting message for the same reason the scan's
	// does: the context is created inside the Cmd, and the registry stores it
	// in the same Update that marks the item running.
	Cancel context.CancelFunc
}
// A pull is asked for from the browser and answered in the Images list, and
// leaving the user on the browser's own spinner meant the one screen that could
// not show either the progress or the result. The switch happens here, once, on
// the keypress that asked for it — it is not a work message dragging the screen
// around behind the user's back, which is what D67 forbids.
func (m Model) handleRegistryPullRequested(msg RegistryPullRequestedMsg) (tea.Model, tea.Cmd) {
	if m.pullingImage(msg.ImageName) {
		return m, m.footer.Warn("Pull already in progress")
	}
	start := jobs.Start(m.pullRun(msg.ImageName), pullOneImageCmd(msg.ImageName))

	// closeMultiRegistryBrowser carries the deselection the next visit reopens
	// on, so the browser is closed through it rather than by hand.
	closed, closeCmd := m.closeMultiRegistryBrowser()
	next, ok := closed.(Model)
	if !ok {
		return closed, tea.Batch(closeCmd, start)
	}
	next.activeTab = tabImages
	next.updateImageTable()
	return next, tea.Batch(closeCmd, start)
}

// handleRegistryPullComplete processes the result of a pull.
//
// It does not depend on the browser any more: the pull outlives it now that
// asking for one closes it, and a completion that returned early on a nil
// browser would skip the refresh that makes the pulled image appear.
func (m Model) handleRegistryPullComplete(msg RegistryPullCompleteMsg) (tea.Model, tea.Cmd) {
	if msg.Replaces != "" {
		return m.handleImageUpdated(msg)
	}
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] pull %s: %v", msg.ImageName, msg.Err)
		return m, m.footer.Error("Pull failed — check logs")
	}
	return m, tea.Batch(fetchImages(), m.footer.Info("Image pulled: "+msg.ImageName))
}

// handleRegistryTagDirectScan starts a direct remote Trivy scan without pulling the image.
func (m Model) handleRegistryTagDirectScan(msg RegistryTagDirectScanMsg) (tea.Model, tea.Cmd) {
	if m.scanningImage(msg.ImageName) {
		return m, m.footer.Warn("Scan already in progress")
	}
	job := imageScanJob{Name: msg.ImageName, Target: msg.ImageName}
	return m, jobs.Start(
		m.scanRun([]string{msg.ImageName}),
		batchScanCmd([]imageScanJob{job}, m.scanOptions()),
	)
}

// unscannedCount returns the number of images not yet scanned
func (m *Model) unscannedCount() int {
	count := 0
	for _, img := range m.images {
		name := img.Name()
		if img.Repository == "<none>" {
			continue
		}
		if _, ok := m.scanCache[name]; !ok {
			count++
		}
	}
	return count
}


func (m ImageScanFinishedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

func (m RegistryPullStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m RegistryPullCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemDone}
	switch {
	case len(m.InUse) > 0:
		t.State = jobs.ItemFailed
		t.Detail = "not updated — the image is in use"
	case m.Err != nil:
		t.State = jobs.ItemFailed
		t.Detail = "pull failed — check logs"
	}
	return t
}

