func TestLivePull(t *testing.T) {
	cfg := &config.Config{}
	report := &scan.Report{Tools: map[scan.ToolID]scan.ToolStatus{scan.ToolCosign: {Available: true, Source: scan.ToolSourceBinary, Binary: "$S/cosign-wrap"}}}
