		d.Policy = func() (trust.Policy, error) { return trust.Policy{Rules: rules}, nil }
		d.Verifier = scan.CosignVerifier{Tool: report.Spec(scan.ToolCosign)}
		res, err := Pull(ctx, c.ref, d)
