1	// Package imagepull is the one way DevDesk pulls an image (§3.82): resolve the
2	// tag to a digest, verify that digest's signature, pull the digest, then name
3	// it the way it was asked for.
4	//
5	// Every pull goes through Pull — the registry browser, G, the MCP — and a test
6	// holds that no other package calls docker.PullImageContext. A second path
7	// would be a pull nobody verified.
8	package imagepull
9	
10	import (
11		"context"
12		"fmt"
13		"log"
14		"strings"
15	
16		"github.com/anthnel/devdesk/internal/trust"
17	)
18	
19	// Deps are the calls a pull makes, injected so the sequence runs without an
20	// engine, a registry or cosign.
21	type Deps struct {
22		// Enabled is scan.image_verification. Off pulls the tag as it always did.
23		Enabled bool
24		// Policy loads ~/.devdesk/trust.yaml. Read on every pull, so an edit takes
25		// effect without restarting.
26		Policy func() (trust.Policy, error)
27		// Verifier checks a signature — cosign, cached.
28		Verifier trust.Verifier
29		// Digest is the digest the registry says ref's tag points to now.
30		Digest func(ref string) (string, error)
31		// Current is the local image ref names, pinned by digest ("" when there is
32		// none): the image continuity compares with.
33		Current func(ref string) string
34		// Pull fetches a reference; Tag names source as target.
35		Pull func(ctx context.Context, ref string) error
36		Tag  func(source, target string) error
37	}
38	
39	// BlockedError is a pull refused because of what the signature check found.
40	// Its message is the Result's reason, which names the rule.
41	type BlockedError struct{ Result trust.Result }
42	
43	func (e *BlockedError) Error() string { return e.Result.Reason() }
44	
45	// Pull verifies, then pulls. The Result says what the check found; a Warn is
46	// carried there, for the caller to show. An error is either a *BlockedError or
47	// the engine's own failure.
48	func Pull(ctx context.Context, ref string, d Deps) (trust.Result, error) {
49		if !d.Enabled {
50			return trust.Result{}, d.Pull(ctx, ref)
51		}
52		res, pinned := check(ctx, ref, d.Current(ref), d)
53		if res.Decision == trust.Block {
54			return res, &BlockedError{Result: res}
55		}
56		if pinned == "" {
57			// The digest could not be had: nothing was verified, and the decision
58			// above said that may go ahead — pull the tag as asked.
59			return res, d.Pull(ctx, ref)
60		}
61		if err := d.Pull(ctx, pinned); err != nil {
62			return res, err
63		}
64		if pinned == ref {
65			return res, nil
66		}
67		// The digest is pulled nameless; the tag it was asked for points at it
68		// only once named.
69		return res, d.Tag(pinned, ref)
70	}
71	
72	// Check answers for ref without pulling it — what the Remediation tab shows
73	// next to a candidate, and the scan's finding on the image in use. current is
74	// the image ref would replace, as a tag or pinned; "" for none. Off answers
75	// nothing: a zero Result.
76	func Check(ctx context.Context, ref, current string, d Deps) trust.Result {
77		if !d.Enabled {
78			return trust.Result{}
79		}
80		if current != "" && trust.Digest(current) == "" {
81			// Continuity compares with what the tag in use points to now; a
82			// registry that will not say leaves nothing to continue.
83			current = pin(current, d)
84		}
85		res, _ := check(ctx, ref, current, d)
86		return res
87	}
88	
89	// check is the verification Pull and Check share. pinned is the digest the
90	// verdict is about, "" when the registry would not give one.
91	func check(ctx context.Context, ref, current string, d Deps) (trust.Result, string) {
92		policy, err := d.Policy()
93		if err != nil {
94			// A policy that cannot be read is not an empty one: the rules it holds
95			// would be dropped in silence, which is the weakening the strict parse
96			// exists to prevent. Refused, naming the file.
97			return trust.Result{Verdict: trust.Failed, Decision: trust.Block, Err: err,
98				Rule: trust.Rule{Source: trust.SourceUser, Origin: "trust.yaml is invalid: " + err.Error()}}, ""
99		}
100		pinned := ref
101		if trust.Digest(ref) == "" {
102			digest, err := d.Digest(ref)
103			if err != nil {
104				return unresolved(ref, policy, err), ""
105			}
106			pinned = trust.Repository(ref) + "@" + digest
107		}
108		res := trust.Evaluate(ctx, policy, d.Verifier, pinned, current)
109		if res.Err != nil {
110			log.Printf("ERROR [imagepull] verify %s: %v", pinned, res.Err)
111		}
112		return res, pinned
113	}
114	
115	// unresolved is a tag whose digest the registry did not give. Nothing can be
116	// verified — so it is a Failed verdict, decided by the rule that would have
117	// applied: a user rule refuses, anything else goes ahead and warns.
118	func unresolved(ref string, policy trust.Policy, cause error) trust.Result {
119		log.Printf("ERROR [imagepull] resolve %s: %v", ref, cause)
120		res := trust.Result{Verdict: trust.Failed, Decision: trust.Decide(trust.Failed, trust.SourceContinuity),
121			Err: fmt.Errorf("resolve %s: %w", ref, cause)}
122		if rule, ok := policy.Lookup(ref); ok {
123			if rule.Mode == trust.ModeNone {
124				return trust.Result{Rule: rule}
125			}
126			res.Rule, res.Decision = rule, trust.Decide(trust.Failed, rule.Source)
127		}
128		return res
129	}
130	
131	// pin resolves a tag to its registry digest, "" when the registry will not say.
132	func pin(ref string, d Deps) string {
133		digest, err := d.Digest(ref)
134		if err != nil {
135			return ""
136		}
137		return trust.Repository(ref) + "@" + digest
138	}
139	
140	// localDigest picks, among an image's repo digests, the one of ref's own
141	// repository — an image pulled under two names carries both.
142	func localDigest(ref string, repoDigests []string) string {
143		repo := trust.Repository(ref)
144		for _, rd := range repoDigests {
145			name, digest, ok := strings.Cut(rd, "@")
146			if ok && trust.Repository(name) == repo {
147				return repo + "@" + digest
148			}
149		}
150		return ""
151	}

