// Bool reads a toggle.
func (f field) Bool(c *config.Config) bool {
	if f.get != nil {
		return f.get(c)
	}
	return *f.flag(c)
}

// Toggle flips a toggle and reports the new value.
func (f field) Toggle(c *config.Config) bool {
	if f.set != nil {
		on := !f.get(c)
		f.set(c, on)
		return on
	}
	p := f.flag(c)
	*p = !*p
	return *p
}

